import {effectiveTracks,provisionalTracks,SIGNAL_LABELS} from './evidence.js?v=1.0.0';
import {csvCell,REGIONS} from './core.js?v=1.0.0';
import {placementOf,OUTCOMES} from './placement.js?v=1.0.0';
export const CSV_HEADERS=['姓名','博士院校','博士项目','培养地区','北美研究排名（UTD四刊2021–2025）','领域标签','研究领域','研究主题','研究方法','JMP','JMP核验依据','JMP资料链接','个人主页','CV','求职季','来源名单年','首次入职年','毕业年','首次机构','首次岗位','所选去向口径','统计机构','统计岗位','统计分类','统计地区','最终安排入职年','最终安排状态','最终安排依据','本科院校','本科地区','中国公民公开确认','华裔本人自述','核验备注','来源','核验日期','研究方向筛选口径','用于筛选的方向','暂定研究方向','暂定理由','暂定依据','区域公开活动','岗位家族','Tenure状态','Tenure证据状态','去向依据类别','字段证据ID','研究主题原文','研究方法原文','导出口径'];
export function csvRows(records,basis='final',researchMode='standard',metadata={}){
  return records.map(r=>{const p=placementOf(r,basis);return [r.name,r.school,r.program,REGIONS[r.origin],r.origin_rank,r.tracks.join('; '),r.fields.join('; '),r.topics.join('; '),r.methods.join('; '),r.jmp,r.jmp_evidence,r.jmp_url,r.homepage,r.cv_url,r.market_cycle,r.source_cohort_year,r.placement_year,r.graduation_year,r.destination,r.role,basis,p.destination,p.role,OUTCOMES[p.category],REGIONS[p.destination_region]||p.destination_region,r.final_placement?.year,r.final_placement?.status,r.final_placement?.evidence,r.undergraduate?.institution,REGIONS[r.undergraduate?.region]||'未核验',r.identity?.chinese_national?.value||'unknown',r.identity?.chinese_heritage?.value||'unknown',r.notes,r.sources.map(s=>s.url).join(' | '),r.checked_at,researchMode,effectiveTracks(r,researchMode).join('; '),provisionalTracks(r).join('; '),r.research_inference?.reason,r.research_inference?.source_urls.join(' | '),(r.regional_signals||[]).map(s=>[SIGNAL_LABELS[s.kind],s.region,s.observed_date,s.institution,s.evidence,s.source_url].join(' · ')).join(' | '),p.job_family,p.tenure_status,p.tenure_evidence_status,p.basis,(r.claim_ids||[]).join('; '),(r.topics_raw||r.topics).join('; '),(r.methods_raw||r.methods).join('; '),JSON.stringify(metadata)]});
}
export function buildCsv(records,basis='final',researchMode='standard',metadata={}){return '\uFEFF'+[CSV_HEADERS,...csvRows(records,basis,researchMode,metadata)].map(row=>row.map(csvCell).join(',')).join('\r\n');}
